'use strict';
let data, localToken = null, canRun = false, page = 'runtime', selectedMilestone = 'M7', systemTab = 'architecture', packetIndex = 0, running = false;
let lastRunError = '', diagnosticsOpen = false;
let packetVector = 'noop', capturedPacket = null, linkView = null;
let requirementQuery = '', requirementMilestone = 'all', requirementState = 'all';
const $ = selector => document.querySelector(selector);
const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const date = value => value ? new Date(value).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}) : 'Not recorded';
const badge = (label, style='') => `<span class="pill ${style}">${escapeHTML(label)}</span>`;
const heading = (eyebrow,title,description,action='') => `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div>${action}</div>`;
const docButton = (file,label) => `<button class="text-button" data-doc="${file}">${label} <span>↗</span></button>`;
const verified = () => data.requirements.filter(item => item.state === 'passed').length;
const panel = (title,content,extra='') => `<section class="panel"><div class="panel-head"><h2>${title}</h2>${extra}</div>${content}</section>`;
const stat = (label,value,suffix,description,symbol='↗',positive=false) => `<div class="stat"><div class="stat-top">${label}<span class="stat-symbol">${symbol}</span></div><div class="stat-value">${value}<small>${suffix}</small></div><div class="stat-bottom ${positive?'green-text':''}">${description}</div></div>`;
const milestonePill = item => badge(item.state === 'active' ? 'In progress' : item.state === 'complete' ? 'Complete' : 'Planned',item.state === 'planned'?'gray':item.state === 'active'?'amber':'');
function overview(){
 const current=data.milestones.find(m=>m.id===data.currentMilestone);
 return heading('PROJECT REFERENCE','Project status','Implementation and test results. Flight controls are in Simulator.')+
 `<div class="stats">${stat('IMPLEMENTED',data.currentMilestone,'',escapeHTML(current.name))}${stat('REQUIREMENTS',verified(),'/ 20','With passing evidence')}${stat('TEST REPORTS',data.reports.length,'','Recorded build results')}${stat('HOSTED CI',data.hostedCI.status==='passed'?'Passed':'Pending','','Repository setup required')}</div>`+
 panel('Verification records',`<div class="panel-body">${data.reports.map((r,i)=>`<div class="build-row"><div><strong>${escapeHTML(r.label)}</strong><small>${date(r.recordedAt)}</small></div><button class="text-button" data-report="${i}">${r.tests.filter(t=>t.state==='passed').length}/${r.tests.length} checks ↗</button></div>`).join('')||'<p>No reports available.</p>'}</div>`)+
 `<div class="section-head"><h2>Implementation notes</h2></div><div class="source-grid">${data.documents.map(d=>`<button class="source-button" data-doc="${d.file}">${escapeHTML(d.title)} ↗</button>`).join('')}</div>`;
}
function packets(){return heading('PROTOCOL TOOL','Packet inspector','Decode packet bytes and check their CRC. This tool does not send commands.')+packetLab();}
let hkPeriodDraft = 1000, injectionDraft = 5;
let flightState = null, flightBusy = false, flightPolling = false;
const expandedPanels = {};
function disclosure(id,title,body){return `<details class="detail-panel" data-disclosure="${id}" ${expandedPanels[id]?'open':''}><summary>${title}</summary><div class="disclosure-body">${body}</div></details>`;}
document.addEventListener('toggle',event=>{if(event.target.dataset?.disclosure)expandedPanels[event.target.dataset.disclosure]=event.target.open;},true);
function flightPanel(){
 const live=!!localToken, f=live?flightState:data.flightRecord?.session;
 const h=f?.hk, fields=h?.packet?.fields, active=live&&f?.running;
 const obs=f?.observation, obsFresh=active&&obs&&f.observationAgeSeconds<.5;
 const mode=obsFresh?obs.mode:fields?.mode;
 const disabled=(!active||(flightBusy||scenarioActive()))?'disabled':'';
 const metrics=[['BATTERY',fields&&fields.battery_percent!==255?fields.battery_percent+'%':'—'],
 ['TEMPERATURE',fields&&fields.temperature_centi_c!==-32768?fields.temperature_centi_c/100+' °C':'—'],
 ['UPTIME',fields?fields.uptime_s+' s':'—'],['VOLTAGE',fields&&fields.battery_mv!==65535?(fields.battery_mv/1000).toFixed(2)+' V':'—']];
 const technical=`<div class="controls rate-control"><label for="hk-period">NOMINAL HK period (ms)</label><input id="hk-period" type="number" min="250" max="10000" step="1" value="${hkPeriodDraft}" ${disabled}><button class="button" data-flight="set_hk_rate" ${!active||(flightBusy||scenarioActive())||![2,3].includes(mode)?'disabled':''}>Apply period</button><button class="button" data-flight="reset_counters" ${disabled}>Reset counters</button></div><p class="mini-copy">250–10,000 ms. SAFE uses 10 seconds; LOW_POWER uses 5 seconds. Reset clears command counts only.</p><dl class="session-facts"><div><dt>Accepted / rejected</dt><dd>${fields?.accepted??'—'} / ${fields?.rejected??'—'}</dd></div><div><dt>Last reported fault</dt><dd>${fields?faultNames[fields.last_fault]||fields.last_fault:'—'}</dd></div><div><dt>HK sequence</dt><dd>${h?.packet?.sequence??'—'}</dd></div><div><dt>UDP flight / ground</dt><dd>${f?.flightPort||5000} / ${f?.groundPort||5001}</dd></div><div><dt>Invalid packets / unmatched ACKs</dt><dd>${f?.invalidPackets??0} / ${f?.unmatchedAcks??0}</dd></div></dl><p class="mini-copy">Readings come from received HK and can lag during an outage. Voltage is a fixed simulated baseline. The test observation is a separate local channel.</p>`;
 const stackNames=['link','command','mode','telemetry','sensors','watchdog'];
 const healthHK=`<p class="mini-copy">Received HK · ${h?.stale?'stale':h?'latest packet':'unavailable'}. FreeRTOS stack-buffer high-water marks are minimum unused StackType_t elements. The POSIX port uses separate pthread stacks; these values do not measure host stack usage.</p><div class="watchdog-grid">${stackNames.map((name,i)=>`<div><strong>${name}</strong><span>${fields?.['stack_'+name]!=null&&fields['stack_'+name]!==65535?fields['stack_'+name]+' free elements':'—'}</span><small>${fields?.task_stalled_mask==null||fields?.['stack_'+name]===65535?'No health data':fields.task_stalled_mask&(1<<(i+1))?'Stall detected':'Checking in'}</small></div>`).join('')}</div><dl class="session-facts"><div><dt>Dropped flight events</dt><dd>${fields?.dropped_events??'—'}</dd></div></dl><p class="mini-copy">Mode stalls are detected independently and reported here while telemetry works. A permanently stalled Mode cannot enter SAFE. Phase 2 adds a hardware watchdog reset.</p>`;
 const history=`<div class="table-wrap"><table><thead><tr><th>COMMAND</th><th>SEQUENCE</th><th>RESULT</th><th>ROUND TRIP</th><th>ACK SEQUENCE</th></tr></thead><tbody>${(f?.history||[]).map(r=>`<tr><td>${escapeHTML(r.command.toUpperCase())}${r.argument?' · '+r.argument:''}</td><td>${r.sequence}</td><td>${badge(r.status||r.state,r.status==='OK'?'':'amber')}</td><td>${r.rttMs==null?'—':r.rttMs+' ms'}</td><td>${r.ackSequence??'—'}</td></tr>`).join('')}</tbody></table>${f?.history?.length?'':'<div class="empty-state">No commands sent in this session.</div>'}</div><p class="mini-copy">Measured round trips. Commands time out after 1 second and are never retried automatically.</p>`;
 return `<section class="panel flight-session"><div class="panel-head"><h2>Flight controls</h2>${badge(active?(f.testBuild?'Test flight':'Production flight'):live?'Stopped':'Recorded','gray')}</div><div class="panel-body">
 <div class="session-actions controls"><button class="button primary" data-flight="start_test" ${!live||active||(flightBusy||scenarioActive())||!f?.testAvailable?'disabled':''}>Start test flight</button><button class="button" data-flight="start" ${!live||active||(flightBusy||scenarioActive())||!f?.available?'disabled':''}>Start flight</button><button class="button ghost" data-flight="stop" ${!live||(!active&&f?.state!=='process_exited')||(flightBusy||scenarioActive())?'disabled':''}>Stop flight</button></div>
 <p class="mini-copy session-hint">${active?(f.testBuild?'Test flight · fault injections enabled.':'Production flight · fault injections unavailable.'):'Choose Test flight to try faults, or Start flight for normal operation.'}</p>
 <div class="mode-control" aria-label="Operating mode"><div class="live-modes">${[[1,'SAFE'],[2,'NOMINAL'],[3,'LOW POWER']].map(([id,name])=>`<span class="${active&&mode===id?'current':''}" ${active&&mode===id?'aria-current="true"':''}>${name}</span>`).join('')}</div><p class="mode-source">${active?(obsFresh?'Mode · live test observation':h?.stale?'Mode · stale HK reading':'Mode · last received HK'):'No active flight'}</p><div class="controls"><button class="button" data-flight="nominal" ${disabled}>Enter NOMINAL</button><button class="button" data-flight="safe" ${disabled}>Enter SAFE</button></div></div>
 <div class="empty-telemetry ${fields?'received-hk':''}">${metrics.map(([name,value])=>`<div class="empty-metric"><span>${name}</span><strong>${escapeHTML(value)}</strong></div>`).join('')}</div><div class="telemetry-actions"><span class="mini-copy">${live?(h?`HK · ${h.ageSeconds.toFixed(1)} s ago${h.stale?' · stale':''}`:'Awaiting telemetry'):'Recorded readings'}</span><button class="button small" data-flight="noop" ${disabled}>Send NOOP</button><button class="button small" data-flight="request_hk" ${disabled}>Request HK</button></div>
 ${scenarioActive()?'<p role="status">Scenario running · controls locked</p>':flightBusy?'<p role="status">Sending command…</p>':''}${f?.error?`<p role="alert" class="amber-text">${escapeHTML(f.error)}</p>`:''}
 </div></section>${scenarioPanel(f,live)}${faultPanel(f,live)}${disclosure('hk-health','Stack & watchdog health · received HK',healthHK)}${disclosure('settings','Telemetry settings & session details',technical)}${disclosure('telemetry','Telemetry timing & flight events',telemetryPanel(f,live))}${disclosure('commands',`Command history · ${f?.history?.length||0}`,history)}`;
}
let scenarioDraft='low_battery',scenarioPending=false;
const scenarioOptions={low_battery:['Low battery recovery','Battery 15% → LOW_POWER → automatic NOMINAL.'],critical_battery:['Critical battery protection','Battery 5% → SAFE → fault clears → ground recovery.'],over_temperature:['Over-temperature protection','Temperature 61 °C → SAFE → fault clears → ground recovery.'],telemetry_stall:['Telemetry stall recovery','Pause telemetry → watchdog detects the stall → SAFE → ground recovery.']};
function scenarioActive(){return scenarioPending||flightState?.scenario?.state==='running';}
function scenarioPanel(f,live){
 const r=f?.scenario,active=r?.state==='running';
 const unavailable=!live?'Open the local console to run scenarios.':!r?'Restart the Python console to enable scenarios.':!f.testAvailable?'Build the test flight executable first.':(f.running||f.state==='process_exited')&&!active?'Stop the current flight before starting a scenario.':'';
 return `<section class="panel scenario-panel"><div class="panel-head"><h2>Live scenarios</h2>${badge(r?.state||'Ready',r?.state==='failed'?'red':r?.state==='running'?'amber':'gray')}</div><div class="panel-body"><p>Run a complete test and verify the actual flight response. Each scenario starts its own test flight.</p><div class="controls fault-controls"><label for="scenario-choice">Scenario</label><select id="scenario-choice" ${active||scenarioPending?'disabled':''}>${Object.entries(scenarioOptions).map(([id,v])=>`<option value="${id}" ${scenarioDraft===id?'selected':''}>${v[0]}</option>`).join('')}</select><button class="button primary" data-scenario="start" ${unavailable||active||scenarioPending||flightBusy?'disabled':''}>Run scenario</button><button class="button" data-scenario="cancel" ${!active||scenarioPending?'disabled':''}>Cancel scenario</button></div><p class="mini-copy">${escapeHTML(scenarioOptions[scenarioDraft][1])}</p><p class="mini-copy" role="status">${escapeHTML(active?'Scenario controls the flight. Manual commands are temporarily locked.':r?.state==='passed'&&f?.running?'Passed. Manual controls are available. Stop flight to run another scenario.':unavailable||'A passing run leaves the flight in NOMINAL. Cancel or failure stops it.')}</p>${r?.name?`<h3 class="scenario-title">${escapeHTML(r.name)}</h3>${r.finishedAt?`<p class="mini-copy">Completed ${date(r.finishedAt)} · recorded result; live flight state can change afterward.</p>`:''}`:''}<ol class="scenario-steps">${(r?.steps||[]).map(step=>`<li class="${step.state}"><span>${badge(step.state,step.state==='failed'?'red':step.state==='running'?'amber':'gray')}</span><div><strong>${escapeHTML(step.name)}</strong>${step.detail?.transitionMs!=null?`<small>${step.detail.mode} in ${step.detail.transitionMs} ms · limit ${step.detail.limitMs} ms</small>`:step.detail?.mode?`<small>${escapeHTML(step.detail.mode)}</small>`:''}${step.error?`<small>${escapeHTML(step.error)}</small>`:''}</div></li>`).join('')}</ol>${r?.error?`<p role="alert" class="amber-text">${escapeHTML(r.error)}</p>`:''}${r?.reportAvailable?'<a class="button small" href="/api/scenario/report.json" download>Download scenario report</a>':''}</div></section>`;
}
async function scenarioAction(action){
 if(!localToken||scenarioPending)return;
 scenarioPending=true;updateFlightPanel();
 try{
  const response=await fetch('/api/scenario/'+action,{method:'POST',headers:{'X-Kestrel-Token':localToken,'Content-Type':'application/json'},body:action==='start'?JSON.stringify({scenario:scenarioDraft}):undefined,signal:AbortSignal.timeout(5000)});
  const result=await response.json();if(!response.ok)throw Error(result.error||'Scenario request failed');
  if(flightState)flightState.scenario=result;
 }catch(error){notify(error.message);}
 finally{scenarioPending=false;await pollFlight();}
}
document.addEventListener('change',event=>{if(event.target.id==='scenario-choice'){scenarioDraft=event.target.value;updateFlightPanel();}});
document.addEventListener('click',event=>{const action=event.target.closest('[data-scenario]')?.dataset.scenario;if(action)scenarioAction(action);});
const faultNames=['None','Low battery','Critical battery','Over temperature','Under temperature','Sensor dropout','Task stall','Queue congestion'];
const taskNames=['System','Link','Command','Mode','Telemetry','Sensors','Watchdog'];
const injectionNames=['None','Stall link','Stall command','Stall telemetry','Stall sensors','Battery 15%','Battery 5%','Temperature 61 °C','Temperature −21 °C','Sensor dropout','Stall Mode (detection only)'];
function faultPanel(f,live){
 const o=f?.observation, fresh=f?.running&&o&&f.observationAgeSeconds<.5;
 const phase=o?(o.timeMs<o.injectionStartMs?'Armed':o.timeMs<o.injectionEndMs?'Active':'Expired'):'None';
 const remaining=o?Math.max(0,(o.injectionEndMs-o.timeMs)/1000).toFixed(1):'0.0';
 const blocked=!live?'Open the local simulator to inject a fault.':(flightBusy||scenarioActive())?'Scenario or command in progress. Use Cancel scenario to stop a scenario.':!f?.running?'Start a test flight to enable injections.':!f.testBuild?'This is a production flight. Stop it, then start a test flight.':!fresh?'Waiting for a fresh test observation…':o.mode===1?'The spacecraft is in SAFE. Enter NOMINAL to enable injections.':phase==='Active'||phase==='Armed'?'An injection is already running. Wait for it to finish.':'';
 const disabled=!!blocked;
 const setupAction=live&&!(flightBusy||scenarioActive())?(!f?.running&&f?.testAvailable?'<button class="button small" data-flight="start_test">Start test flight</button>':f?.running&&!f.testBuild?'<button class="button small" data-flight="stop">Stop production flight</button>':fresh&&o.mode===1?'<button class="button small" data-flight="nominal">Enter NOMINAL</button>':''):'';
 const modeNames=['BOOT','SAFE','NOMINAL','LOW_POWER'];
 const activeFaults=o?[...faultNames.keys()].filter(i=>i>0&&(o.faultMask&(1<<i))).map(i=>faultNames[i]):[];
 if(o?.stalledMask)activeFaults.push(...taskNames.map((n,i)=>o.stalledMask&(1<<i)?n+' stalled':null).filter(Boolean));
 function sensorPlot(field,label,unit,min,max){
  const rows=(f?.samples||[]).filter(s=>s.packet.apid===16).slice(-60);
  const values=rows.map(s=>{const v=s.packet.fields[field];return v===255&&field==='battery_percent'||v===-32768?null:field==='temperature_centi_c'?v/100:v;});
  const points=values.map((v,i)=>v===null?'':`${i===0||values[i-1]===null?'M':'L'}${20+i*560/Math.max(1,values.length-1)},${125-(v-min)/(max-min)*100}`).join(' ');
  return `<section class="panel"><div class="panel-head"><h2>${label}</h2>${badge('Received HK','gray')}</div><div class="panel-body"><svg viewBox="0 0 600 150" role="img" aria-label="${label} history, ${min} to ${max} ${unit}"><path d="M20 25V125H580" stroke="#45505a" fill="none"/><text x="24" y="20" fill="#a5adb6" font-size="12">${max} ${unit}</text><path d="${points}" fill="none" stroke="#a9df8c" stroke-width="2"/>${values.map((v,i)=>v===null?'':`<circle cx="${20+i*560/Math.max(1,values.length-1)}" cy="${125-(v-min)/(max-min)*100}" r="3" fill="#a9df8c"><title>${v} ${unit}</title></circle>`).join('')}</svg><p class="mini-copy">Latest 60 received HK samples. Missing values are unavailable; no new points arrive while telemetry is stalled.</p></div></section>`;
 }
 return `<section class="panel fault-panel"><div class="panel-head"><h2>Fault testing</h2>${badge(f?.testBuild?'Test flight':'Test flight required',f?.testBuild?'':'gray')}</div><div class="panel-body"><p>${f?.testBuild?'Apply one condition for 5 seconds and watch the flight respond.':'Fault tests require a test flight.'}</p><div class="controls fault-controls"><label for="fault-choice">Test condition</label><select id="fault-choice">${injectionNames.slice(1).map((name,i)=>`<option value="${i+1}" ${Number(injectionDraft)===i+1?'selected':''}>${name}</option>`).join('')}</select><button class="button primary" data-flight="inject_fault" ${disabled?'disabled':''}>Inject for 5 seconds</button></div><div class="injection-readiness" role="status"><p>${escapeHTML(blocked||'Ready to inject the selected condition for 5 seconds.')}</p>${setupAction}</div><p class="mini-copy">15% battery returns to NOMINAL automatically. Critical faults stay in SAFE after clearing; use Enter NOMINAL to recover. Mode-stall testing verifies detection in received HK, not SAFE entry.</p>
 ${f?.testBuild?`<p class="observation-source">Test observation · ${fresh?'live':'unavailable / stale'} · separate from received telemetry${f.observationError?' · '+escapeHTML(f.observationError):''}</p><div class="recovery-summary"><strong>${fresh?modeNames[o.mode]:'—'}</strong><span>${fresh?(activeFaults.join(' · ')||'No active faults'):'Awaiting fresh observation'}</span><span>${o?.injection?`${injectionNames[o.injection]} · ${phase==='Expired'?'finished':phase+' · '+remaining+' s remaining'}`:'No injection yet'}</span></div><p class="mini-copy">${o?.injection&&o.changedAtMs>=o.injectionStartMs&&o.changedAtMs<o.injectionEndMs?`Mode transition during injection: ${o.changedAtMs-o.injectionStartMs} ms after it began.`:'Open the recovery timeline to review mode changes.'}</p>${disclosure('health','Task health & recovery timeline',`<h3>Task check-ins</h3><div class="watchdog-grid">${taskNames.slice(1).map((name,i)=>`<div><strong>${name}</strong><span>${fresh?o.checkinAgeMs[i]+' ms ago':'—'}</span><small>${fresh?o.misses[i]+' / 3 missed windows':'No fresh observation'}</small></div>`).join('')}</div><p class="mini-copy">A check-in older than 500 ms misses a one-second window. Three consecutive misses trigger SAFE. Mode, Watchdog and scheduler must remain operational.</p><h3>Recovery timeline</h3><div class="table-wrap"><table><thead><tr><th>FLIGHT TIME</th><th>MODE</th><th>ACTIVE CONDITIONS</th><th>INJECTION</th></tr></thead><tbody>${(f.recoveryTimeline||[]).map(r=>`<tr><td>${r.timeMs} ms</td><td>${modeNames[r.mode]}</td><td>${faultNames.filter((n,i)=>i>0&&(r.faultMask&(1<<i))).join(', ')}${r.stalledMask?' · '+taskNames.filter((n,i)=>r.stalledMask&(1<<i)).join(', ')+' stalled':''}${!r.faultMask&&!r.stalledMask?'Clear':''}</td><td>${r.injection?injectionNames[r.injection]+' · '+r.injectionPhase:'None'}</td></tr>`).join('')}</tbody></table></div><p class="mini-copy">Mode transition committed at ${o?.changedAtMs??'—'} ms. Dropped flight events: ${o?.droppedEvents??'—'}. Observation snapshots and timeline are bounded; the complete observation log is saved locally alongside telemetry CSV.</p>`)}`:''}</div></section>${disclosure('sensors','Sensor history',`<div class="timing-grid">${sensorPlot('battery_percent','Battery','%',0,100)}${sensorPlot('temperature_centi_c','Temperature','°C',-30,70)}</div>` )}`;
}
document.addEventListener('change',event=>{if(event.target.id==='fault-choice')injectionDraft=Number(event.target.value);});
function telemetryPanel(f,live){
 const samples=f?.samples||[], modes=['BOOT','SAFE','NOMINAL','LOW_POWER'];
 function timing(apid,label,color){
  const values=samples.filter(s=>s.packet.apid===apid).slice(-60);
  const intervals=values.slice(1).map((s,i)=>({t:s.packet.time_ms,ms:(s.packet.time_ms-values[i].packet.time_ms+4294967296)%4294967296}));
  const max=Math.max(1000,...intervals.map(v=>v.ms));
  const points=intervals.map((v,i)=>`${20+i*560/Math.max(1,intervals.length-1)},${125-v.ms/max*100}`).join(' ');
  return `<section class="panel timing-panel"><div class="panel-head"><h2>${label} packet interval</h2>${badge(values.length+' retained','gray')}</div><div class="panel-body"><p class="mini-copy">${apid===17&&f?.hk?.packet?.fields.mode!==2?'Paused outside NOMINAL · last observed interval':'Last observed interval'}</p><strong>${intervals.length?intervals.at(-1).ms+' ms':'Awaiting two packets'}</strong><svg viewBox="0 0 600 150" role="img" aria-label="${label} intervals in milliseconds, oldest on left, zero at bottom and ${max} at top"><path d="M20 25V125H580" fill="none" stroke="#45505a"/><text x="24" y="20" fill="#a5adb6" font-size="12">${max} ms</text><polyline points="${points}" fill="none" stroke="${color}" stroke-width="2"/>${intervals.map((v,i)=>`<circle cx="${20+i*560/Math.max(1,intervals.length-1)}" cy="${125-v.ms/max*100}" r="3" fill="${color}"><title>${v.ms} ms at flight time ${v.t} ms</title></circle>`).join('')}</svg><p class="mini-copy">Intervals from flight packet timestamps. ${apid===16?'Includes requested and mode-entry HK, which can shorten intervals.':'ATT is sent only in NOMINAL. Baseline angular rates are zero; unavailable samples use explicit sentinels.'}</p></div></section>`;
 }
 return `<div class="section-head"><h2>Telemetry timing</h2>${live&&f?.logAvailable?'<a class="button small" href="/api/flight/log.csv" download>Download telemetry CSV</a>':''}</div><p class="mini-copy">${f?.loggedPackets??0} packets logged this session. Plots show up to 60 packets per type from the latest 240 samples. CSV keeps every received valid telemetry packet, including ACKs and events.</p><div class="timing-grid">${timing(16,'HK','#a9df8c')}${timing(17,'ATT','#75bde7')}</div><div class="section-head"><h2>Mode and fault events</h2></div><div class="table-wrap"><table><thead><tr><th>FLIGHT TIME</th><th>EVENT</th><th>TRANSITION</th></tr></thead><tbody>${(f?.modeEvents||[]).map(s=>`<tr><td>${s.packet.time_ms} ms</td><td>${({1:'Mode changed',2:'Fault detected',3:'Fault cleared'})[s.packet.fields.id]||s.packet.fields.id}</td><td>${s.packet.fields.id===1?`${modes[s.packet.fields.parameter_1]} → ${modes[s.packet.fields.parameter_2]}`:`${faultNames[s.packet.fields.parameter_1]||s.packet.fields.parameter_1} · ${taskNames[s.packet.fields.parameter_2]||'System'}`}</td></tr>`).join('')}</tbody></table>${f?.modeEvents?.length?'':'<div class="empty-state">No mode events received.</div>'}</div>`;
}
document.addEventListener('input',event=>{if(event.target.id==='hk-period')hkPeriodDraft=event.target.value;});
function inspectLivePacket(event){capturedPacket={...event};location.hash='packets';render();}
// Keep live controls mounted: replacing a focused select closes its native menu.
function patchFlightDOM(current,next){
 if(current.isEqualNode(next))return;
 if(current.nodeType!==next.nodeType||current.nodeName!==next.nodeName){
  current.replaceWith(next.cloneNode(true));return;
 }
 if(current.nodeType===Node.TEXT_NODE){current.textContent=next.textContent;return;}
 if(current.nodeType!==Node.ELEMENT_NODE)return;
 for(const attribute of [...current.attributes]){
  if(!next.hasAttribute(attribute.name))current.removeAttribute(attribute.name);
 }
 for(const attribute of next.attributes){
  if(current.getAttribute(attribute.name)!==attribute.value)current.setAttribute(attribute.name,attribute.value);
 }
 const oldChildren=[...current.childNodes],newChildren=[...next.childNodes];
 newChildren.forEach((child,index)=>{
  if(oldChildren[index])patchFlightDOM(oldChildren[index],child);
  else current.appendChild(child.cloneNode(true));
 });
 oldChildren.slice(newChildren.length).forEach(child=>child.remove());
}
function updateFlightPanel(){
 const container=$('#flight-view');if(!container)return;
 const next=container.cloneNode(false);
 next.innerHTML=flightPanel();
 patchFlightDOM(container,next);
 linkView?.update(flightState);
}
async function pollFlight(){
 if(!localToken||flightPolling||flightBusy)return;
 flightPolling=true;
 try{const response=await fetch('/api/flight',{cache:'no-store',signal:AbortSignal.timeout(3000)});if(!response.ok)throw Error('Local flight status unavailable');flightState=await response.json();}
 catch(error){flightState={state:'disconnected',running:false,available:false,error:error.message};}
 finally{flightPolling=false;updateFlightPanel();}
}
async function flightAction(action){
 if(!localToken||flightBusy||scenarioActive())return;
 const body=action==='set_hk_rate'?JSON.stringify({periodMs:Number(hkPeriodDraft)}):action==='inject_fault'?JSON.stringify({faultId:Number(injectionDraft)}):undefined;
 flightBusy=true;updateFlightPanel();
 try{const response=await fetch('/api/flight/'+action,{method:'POST',headers:{'X-Kestrel-Token':localToken,'Content-Type':'application/json'},body,signal:AbortSignal.timeout(5000)});const result=await response.json();if(!response.ok)throw Error(result.error||'Operation failed');notify(['start','start_test'].includes(action)?'Flight started in SAFE.':action==='stop'?'Flight stopped.':`${action.toUpperCase()}: ${result.status||result.state}${result.rttMs!==null?' · '+result.rttMs+' ms':''}`);}
 catch(error){notify(error.message);}
 finally{flightBusy=false;await pollFlight();}
}
let replayTime=0,replayPlaying=false;
function replayFrame(){
 const mission=data.release?.mission, frames=mission?.frames||[];
 const current=frames.filter(f=>f.timeMs<=replayTime).at(-1)||frames[0];
 if(!current)return '<p>No recorded mission available.</p>';
 const mode=['BOOT','SAFE','NOMINAL','LOW_POWER'][current.mode];
 return `<div class="stats">${stat('RECORDED MODE',mode,'','At the selected recorded checkpoint')}${stat('BATTERY',current.battery??'—','%','Internal test observation')}${stat('RECEIVED PACKETS',current.packets,'','CSV count at this checkpoint')}</div><p><strong>${escapeHTML(current.label)}</strong></p><p class="mini-copy">Playback ${(replayTime/1000).toFixed(1)} s · checkpoint ${(current.timeMs/1000).toFixed(1)} s. Values hold until the next recorded checkpoint.</p>`;
}
function replay(){
 const mission=data.release?.mission;
 if(!mission)return heading('RECORDED DATA','Recorded mission','Run tools/record_m5.py to capture the mission.');
 const last=mission.frames.at(-1).timeMs;
 return heading('RECORDED DATA','Recorded mission','Replay an actual test flight. Playback does not send commands or control your live flight.')+
 `<section class="panel"><div class="panel-body"><p>Recorded ${date(mission.recordedAt)} · ${mission.loggedPackets} decoded packets · all six command types acknowledged.</p><div class="controls"><button class="button" id="replay-toggle">${replayPlaying?'Pause':'Play'}</button><button class="button" id="replay-restart">Restart</button><label for="replay-position">Flight time</label><input id="replay-position" type="range" min="0" max="${last}" value="${replayTime}" step="1" aria-label="Recorded flight time"></div><div id="replay-frame">${replayFrame()}</div><div class="controls"><a class="button" href="kestrel-verification.zip" download>Download verification bundle</a></div><p class="mini-copy">Includes the recorded telemetry CSV, command receipts, inspection records and supplied test reports. Hosted CI: ${escapeHTML(data.hostedCI.status)}.</p></div></section><div class="section-head"><h2>Recorded checkpoints</h2></div><div class="table-wrap"><table><thead><tr><th>FLIGHT TIME</th><th>OBSERVED RESULT</th></tr></thead><tbody>${mission.frames.map(f=>`<tr><td>${(f.timeMs/1000).toFixed(2)} s</td><td>${escapeHTML(f.label)}</td></tr>`).join('')}</tbody></table></div>`;
}
document.addEventListener('click',event=>{
 if(event.target.id==='replay-toggle'){if(replayTime>=data.release.mission.frames.at(-1).timeMs)replayTime=0;replayPlaying=!replayPlaying;event.target.textContent=replayPlaying?'Pause':'Play';}
 if(event.target.id==='replay-restart'){replayTime=0;replayPlaying=false;render();}
});
document.addEventListener('input',event=>{if(event.target.id==='replay-position'){
 replayPlaying=false;replayTime=Number(event.target.value);$('#replay-toggle').textContent='Play';$('#replay-frame').innerHTML=replayFrame();
}});
setInterval(()=>{if(page!=='replay'||!replayPlaying||!data.release?.mission)return;
 const last=data.release.mission.frames.at(-1).timeMs;replayTime=Math.min(last,replayTime+250);
 $('#replay-position').value=replayTime;$('#replay-frame').innerHTML=replayFrame();
 if(replayTime>=last){replayPlaying=false;$('#replay-toggle').textContent='Play';}
},250);
function runtime(){const demo=data.demo,record=demo?.record;return heading('LOCAL SIMULATION','Simulator','Run the spacecraft computer, send commands, and read its telemetry.')+
 `<div class="operator-layout"><div id="flight-view">${flightPanel()}</div><div id="communication-view"></div></div><details id="diagnostics" class="diagnostics" ${diagnosticsOpen||running||lastRunError?'open':''}><summary>Diagnostics · task and queue test</summary><div class="section-head"><h2>Task and queue test</h2><button class="button" id="run-demo" ${!canRun||running?'disabled':''}>${running?'Running…':'Run diagnostic'}</button></div>${lastRunError?`<div class="notice" role="alert" style="margin-bottom:18px"><strong>Latest attempt failed</strong><br>${escapeHTML(lastRunError)} Previous successful results, if any, remain labeled below.</div>`:''}<div class="page-note">${localToken?'Connected to the local runner. The button runs the actual FreeRTOS executable.':'You are viewing an exported snapshot. Open the local console to execute the demo.'} ${!localToken?'<button class="text-button" data-doc="dashboard.md">Local setup ↗</button>':''}</div>`+
 `<div class="dashboard-grid">${panel('Queue exchange',`<div class="runtime-flow ${running?'running':''}"><div class="flow-node"><span>TASK 01</span><strong>Producer</strong></div><div class="flow-arrow">→</div><div class="flow-node queue"><span>STATIC STORAGE</span><strong>Queue × 4</strong></div><div class="flow-arrow">→</div><div class="flow-node"><span>TASK 02</span><strong>Consumer</strong></div></div><div class="metric-row"><div><strong>${record?.messages??'—'}</strong><span>MESSAGES VERIFIED</span></div><div><strong>${record?.checksum??'—'}</strong><span>PAYLOAD CHECKSUM</span></div><div><strong>${record?.elapsed_ticks??'—'}</strong><span>ELAPSED TICKS</span></div></div><div class="panel-body"><p class="mini-copy" style="margin-top:0">20 ordered messages. Every payload checked by the consumer. No spacecraft state is simulated in M0.</p></div>`,badge(running?'Executing':demo?'Recorded run':'Ready',running?'amber':demo?'':'gray'))}${panel('Execution receipt',`<div class="panel-body">${demo?`<div class="build-row"><span class="muted">Result</span>${badge('Passed')}</div><div class="build-row"><span class="muted">Recorded</span><span>${date(demo.recordedAt)}</span></div><div class="build-row"><span class="muted">Wall time</span><span style="font-family:var(--mono)">${demo.wallMs} ms</span></div><div class="build-row"><span class="muted">Source</span><span style="font-size:10px">FreeRTOS executable</span></div><button class="button small full-button" id="export-run">Download run record ↓</button>`:'<p>No execution record yet. Run M0 locally or export a snapshot with a demo result.</p>'}</div>`,badge('Actual output','gray'))}</div>`+
 `<div class="section-head"><h2>Process output</h2><span class="eyebrow">${demo?'LAST SUCCESSFUL RUN':'AWAITING EXECUTION'}</span></div><pre class="terminal">${demo?escapeHTML(JSON.stringify(record,null,2)):'No run captured.'}</pre></details>`;}
function milestones(){const item=data.milestones.find(m=>m.id===selectedMilestone)||data.milestones[0];const associated=data.requirements.filter(r=>r.due===item.id);return heading('PROJECT REFERENCE','Milestones','Implemented features and remaining work.')+`<div class="milestone-layout"><div class="milestone-list" role="group" aria-label="Choose a milestone">${data.milestones.map(m=>`<button class="milestone-card ${m.id===item.id?'selected':''}" aria-pressed="${m.id===item.id}" data-select-milestone="${m.id}"><span>${m.id}</span><div><strong>${escapeHTML(m.name)}</strong><small>${m.state==='active'?'IN PROGRESS':m.state.toUpperCase()}</small></div></button>`).join('')}</div><section class="panel milestone-detail"><div class="eyebrow">MILESTONE ${item.id.slice(1)} / ${data.milestones.length-1}</div><h2>${escapeHTML(item.name)}</h2>${milestonePill(item)}<p style="margin-top:20px">${escapeHTML(item.summary)}</p><ul class="checklist">${item.deliverables.map(d=>`<li><span class="checkmark">${item.id==='M0'||item.state==='complete'?'✓':'○'}</span>${escapeHTML(d)}</li>`).join('')}</ul><div class="detail-section"><h3>ACCEPTANCE GATE</h3><p>${escapeHTML(item.gate)}</p></div><div class="detail-section"><h3>WHAT THE CONSOLE GAINS</h3><p>${escapeHTML(item.gui)}</p></div><div class="detail-section"><h3>REQUIREMENTS DUE</h3><div class="dialog-metadata">${associated.length?associated.map(r=>`<button class="button small" data-requirement="${r.id}">${r.id}</button>`).join(''):'<span class="muted">Infrastructure milestone. No flight requirements claimed.</span>'}</div></div></section></div>`;}
function requirements(){return heading('PROJECT REFERENCE','Verification','Requirements, test results, and checks still pending.',`<a class="button" href="kestrel-verification.zip" download>Download verification bundle</a> <button class="button" id="export-requirements">Export CSV ↓</button>`)+
 `<div class="stats">${stat('TOTAL REQUIREMENTS',20,'','Stable IDs from the specification','☷')}${stat('VERIFIED',verified(),'','Passing evidence supplied','✓',true)}${stat('PENDING',data.requirements.filter(r=>r.state==='pending').length,'','Not yet verified','○')}${stat('FAILED CHECKS',data.requirements.filter(r=>r.state==='failed').length,'','Failures or skipped evidence','!')}</div><div class="filters"><label class="search"><input id="requirement-search" type="search" aria-label="Search requirements" placeholder="Search by ID, behavior or verification…" value="${escapeHTML(requirementQuery)}"></label><select id="requirement-milestone" aria-label="Filter by milestone"><option value="all">All milestones</option>${data.milestones.map(m=>`<option ${m.id===requirementMilestone?'selected':''}>${m.id}</option>`).join('')}</select><select id="requirement-state" aria-label="Filter by verification status"><option value="all">All statuses</option>${['pending','passed','failed'].map(state=>`<option value="${state}" ${state===requirementState?'selected':''}>${state[0].toUpperCase()+state.slice(1)}</option>`).join('')}</select></div><div id="requirement-results"></div>`;}
function requirementRows(){const query=requirementQuery.toLowerCase();const rows=data.requirements.filter(r=>(requirementMilestone==='all'||r.due===requirementMilestone)&&(requirementState==='all'||r.state===requirementState)&&[r.id,r.text,...r.evidence].join(' ').toLowerCase().includes(query));$('#requirement-results').innerHTML=`<div class="table-wrap"><table><thead><tr><th>REQUIREMENT</th><th>EXPECTED BEHAVIOR</th><th>METHOD</th><th>DUE</th><th>EVIDENCE</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="req-id"><button data-requirement="${r.id}">${r.id} ↗</button></td><td class="req-text">${escapeHTML(r.text)}</td><td>${escapeHTML(r.method)}</td><td class="req-id">${r.due}</td><td>${badge(r.state,r.state==='passed'?'':r.state==='failed'?'red':'gray')}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<div class="empty-state">No requirements match these filters.</div>'}</div><div class="row-count">${rows.length} of 20 requirements · Click an ID to inspect its verification plan.</div>`;}
function packetLab(){
 const vectors=data.protocol?.vectors||[];
 const selected=vectors.find(v=>v.name===packetVector)||vectors[0];
 return `<div class="page-note">${capturedPacket?`Editable copy of captured ${escapeHTML(capturedPacket.label)} #${capturedPacket.sequence} · ${capturedPacket.direction==='tx'?'sent':'received'} ${escapeHTML(new Date(capturedPacket.at*1000).toLocaleTimeString())}. Editing here never changes or resends the original message.`:'Reference packets come from the shared codec tests. Paste your own hex bytes or select an example below.'}</div>
 <section class="panel"><div class="panel-head"><h2>Decode packet</h2>${badge('Local computation','gray')}</div><div class="panel-body">
 <label class="eyebrow" for="packet-vector">SHARED TEST VECTOR</label><select id="packet-vector" style="margin:10px 0 18px">${capturedPacket?'<option selected disabled>Captured live packet</option>':''}${['valid','invalid'].map(group=>`<optgroup label="${group==='valid'?'Valid reference packets':'Rejection cases'}">${vectors.filter(v=>v.valid===(group==='valid')).map(v=>`<option value="${escapeHTML(v.name)}" ${!capturedPacket&&v.name===selected?.name?'selected':''}>${escapeHTML(v.name)}${v.valid?'':' · '+v.expected}</option>`).join('')}</optgroup>`).join('')}</select>
 <label class="eyebrow" for="packet-hex">PACKET BYTES / HEX</label><textarea id="packet-hex" rows="3" maxlength="1600" spellcheck="false" aria-label="Packet hex bytes">${escapeHTML(capturedPacket?.hex??selected?.hex??'')}</textarea>
 <div class="controls" style="margin:13px 0 20px"><button class="button primary" id="inspect-packet">Inspect bytes →</button><button class="button" id="corrupt-packet">Flip a CRC bit</button><span class="muted" style="font-size:11px;align-self:center">Browser-local computation · no uplink</span></div><div id="packet-result" aria-live="polite"></div></div></section>
 <div class="section-head"><h2>Shared vector evidence</h2>${badge(vectors.length+' reference cases','gray')}</div><div class="table-wrap"><table><thead><tr><th>REFERENCE</th><th>EXPECTED</th><th>PYTHON CODEC</th><th>BYTES</th></tr></thead><tbody>${vectors.map(v=>`<tr><td class="req-id">${escapeHTML(v.name)}</td><td>${escapeHTML(v.expected)}</td><td>${badge(v.matches?'Matched':'Mismatch',v.matches?'':'red')}</td><td>${v.hex.length/2}</td></tr>`).join('')}</tbody></table></div><p class="mini-copy">Python results are computed when exporting this snapshot. C encoding, decoding and cross-language comparisons are tracked under FSW-005. Counts and rollover are tracked under FSW-006.</p>`;
}
function inspectPacket(){
 const field=$('#packet-hex');if(!field)return;
 const result=KestrelPackets.inspect(field.value);
 const hex=n=>'0x'+n.toString(16).padStart(4,'0').toUpperCase();
 let body=`<div class="inspection-status">${badge(result.ok?'Valid packet':result.error,result.ok?'':'red')}<span>${result.bytes.length} bytes</span></div>`;
 if(result.crc)body+=`<div class="packet-data"><div><span class="eyebrow">RECEIVED CRC</span><strong>${hex(result.crc.received)}</strong></div><div><span class="eyebrow">COMPUTED CRC</span><strong>${hex(result.crc.calculated)}</strong></div><div><span class="eyebrow">CRC CHECK</span><strong class="${result.crc.valid?'green-text':'amber-text'}">${result.crc.valid?'MATCH':'MISMATCH'}</strong></div></div>`;
 if(result.bytes.length)body+=`<div class="byte-grid">${result.bytes.map((b,i)=>`<span class="byte ${i<6?'primary-byte':i<10?'time-byte':i>=result.bytes.length-2?'crc-byte':'payload-byte'}" title="Byte offset ${i}"><small>${i.toString(16).padStart(2,'0')}</small>${b.toString(16).padStart(2,'0').toUpperCase()}</span>`).join('')}</div><p class="mini-copy">Blue: primary header · green: time · slate: payload · amber: CRC</p>`;
 if(result.ok){const p=result.packet;body+=`<div class="packet-data"><div><span class="eyebrow">APID</span><strong>${hex(p.apid)}</strong></div><div><span class="eyebrow">SEQUENCE</span><strong>${p.sequence} / 16383</strong></div><div><span class="eyebrow">ELAPSED TIME</span><strong>${p.time_ms} ms</strong></div></div><h3 style="margin:16px 0 12px">Decoded payload</h3><pre class="terminal">${escapeHTML(JSON.stringify(p.fields,null,2))}</pre>`;}
 else body+='<p class="mini-copy">Rejected. No payload is treated as valid, and nothing is sent to the flight software.</p>';
 $('#packet-result').innerHTML=body;
}
function system(){let content='';if(systemTab==='architecture')content=`<div class="page-note">Target flight architecture · Six application tasks. M4 runs all six application tasks, communicating through static queues.</div><div class="architecture-band"><span>GROUND</span><span class="muted">⇄ UDP / M2 ⇄</span><span>LINK</span><span class="muted">⇄ QUEUES ⇄</span><span>FLIGHT TASKS</span></div><div class="task-grid">${data.tasks.map(t=>`<button class="task-card" data-task="${t.id}"><div style="display:flex;justify-content:space-between">${badge(t.milestone,'gray')}<span class="muted">↗</span></div><h3>${t.name}</h3><p>${escapeHTML(t.owns)}</p><div class="task-meta"><span>${t.priority.toUpperCase()}</span><span>${escapeHTML(t.cadence)}</span></div></button>`).join('')}</div><div class="notice" style="margin-top:20px"><strong>Watchdog scope</strong><br>Stall protection assumes the mode task, watchdog and scheduler remain operational. A stalled telemetry path cannot transmit its own fault event until it recovers.</div>`;
if(systemTab==='modes')content=`<div class="page-note">Design contract · These are transition rules, not the spacecraft’s current state. The simulator supports SAFE ↔ NOMINAL. Sensor and watchdog faults trigger automatic protection.</div><div class="mode-diagram"><span>BOOT<small>Initialization</small></span><span class="muted">→</span><span><b>SAFE</b><small>Ground command →</small></span><span class="muted">⇄</span><span>NOMINAL<small>&lt;20% battery →</small></span><span class="muted">⇄</span><span>LOW_POWER<small>← Recover at ≥30%</small></span></div><div class="modes">${data.modes.map(m=>`<section class="panel mode-card"><h3>${m.id}</h3><p>${escapeHTML(m.detail)}</p><div class="mode-rule">HK: ${m.hk}<br>ATT: ${m.att}</div><div class="mode-rule">${escapeHTML(m.commands)}</div></section>`).join('')}</div><div class="notice" style="margin-top:20px"><strong>Critical faults take precedence.</strong><br>Battery below 10%, temperature outside −20 to 60 °C, dropout, or supported task stall sends the vehicle to SAFE. Automatic recovery never exits SAFE.</div>`;
if(systemTab==='packets')content=packetLab();
if(systemTab==='references')content=`<div class="source-grid">${data.documents.map(doc=>`<button class="source-button" data-doc="${doc.file}">${escapeHTML(doc.title)} <span>↗</span></button>`).join('')}</div><p class="mini-copy">These documents are exported from the project repository alongside each snapshot.</p>`;
return heading('REFERENCE','System reference','Task responsibilities, mode rules, and protocol documentation.',docButton('design.md','Read design decisions'))+`<div class="tabbar" role="group" aria-label="System views">${[['architecture','Task architecture'],['modes','Operating modes'],['packets','Packet lab'],['references','Source documents']].map(([key,label])=>`<button data-system-tab="${key}" class="${key===systemTab?'selected':''}" aria-pressed="${key===systemTab}">${label}</button>`).join('')}</div>${content}`;}
function render(){if(!data)return;linkView?.destroy();linkView=null;page=location.hash.slice(1)||'runtime';if(!['overview','runtime','packets','replay','milestones','requirements','system'].includes(page))page='runtime';document.querySelectorAll('[data-nav]').forEach(link=>{const active=link.dataset.nav===page;link.classList.toggle('active',active);if(active)link.setAttribute('aria-current','page');else link.removeAttribute('aria-current');});$('#breadcrumb').textContent=({runtime:'SIMULATOR',replay:'RECORDED MISSION',packets:'PACKET INSPECTOR',overview:'PROJECT STATUS',requirements:'VERIFICATION',system:'SYSTEM REFERENCE',milestones:'MILESTONES'})[page];$('#main').innerHTML=({overview,runtime,packets,replay,milestones,requirements,system})[page]();if(page==='runtime'){linkView=new LinkView($('#communication-view'),inspectLivePacket);linkView.update(flightState);}if(page==='requirements')requirementRows();if(page==='packets'||(page==='system'&&systemTab==='packets'))inspectPacket();$('#snapshot-time').textContent=`PROJECT DATA · ${date(data.generatedAt)}`;$('#connection').classList.toggle('live',!!localToken);$('#connection').innerHTML=`<i class="dot"></i> ${localToken?'Local console connected':'Saved snapshot'}`;}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function openDialog(title,body,eyebrow='REFERENCE'){$('#dialog-eyebrow').textContent=eyebrow;$('#dialog-body').innerHTML=`<h2>${escapeHTML(title)}</h2>${body}`;$('#detail-dialog').showModal();}
async function openDoc(file){const doc=data.documents.find(d=>d.file===file);if(!doc)return;try{const response=await fetch('docs/'+encodeURIComponent(file));if(!response.ok)throw Error('Document unavailable');const text=await response.text();openDialog(doc.title,`<div class="document-content">${escapeHTML(text)}</div>`,'SOURCE DOCUMENT');}catch(error){notify(error.message);}}
function openRequirement(id){const r=data.requirements.find(r=>r.id===id);if(!r)return;openDialog(r.id,`<p>${escapeHTML(r.text)}</p><div class="dialog-metadata">${badge(r.state,r.state==='passed'?'':r.state==='failed'?'red':'gray')}${badge(r.method,'gray')}${badge('Due '+r.due,'gray')}</div><div class="detail-section"><h3>VERIFICATION ${r.state==='passed'?'EVIDENCE':'PLAN'}</h3><pre>${escapeHTML(r.evidence.join('\n'))}</pre>${data.release?.records?.[id]?`<p>Reviewer: ${escapeHTML(data.release.records[id].reviewer)}</p><p>${escapeHTML(data.release.records[id].scope)}</p><pre>${escapeHTML(JSON.stringify(data.release.records[id],null,2))}</pre>`:''}<p>${r.state==='passed'?'Passing evidence was supplied in this snapshot.':'A planned test name is not a passing result. The relevant check or review record must supply evidence.'}</p></div>`,'REQUIREMENT DETAIL');}
function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function load(showToast=false){try{const response=await fetch('data.json',{cache:'no-store'});if(!response.ok)throw Error('Project snapshot could not be loaded.');data=await response.json();localToken=null;canRun=false;try{const local=await fetch('/api/state',{cache:'no-store',signal:AbortSignal.timeout(2000)});if(local.ok&&local.headers.get('content-type')?.includes('application/json')){const live=await local.json();if(live.data?.schemaVersion===1&&live.token){data=live.data;localToken=live.token;canRun=live.canRun;}}}catch{/* A hosted snapshot has no laptop execution endpoint. */}if(data.schemaVersion!==1)throw Error('Unsupported snapshot format.');render();await pollFlight();if(showToast)notify(localToken?'Refreshed from the local project.':'Reloaded the latest published snapshot.');}catch(error){$('#main').innerHTML=`<div class="empty-state"><h1>Snapshot unavailable</h1><p>${escapeHTML(error.message)}</p><button class="button" style="margin-top:20px" onclick="location.reload()">Try again</button></div>`;}}
async function execute(){if(!canRun||running)return;diagnosticsOpen=true;running=true;lastRunError='';render();try{const response=await fetch('/api/run-m0',{method:'POST',headers:{'X-Kestrel-Token':localToken}});const result=await response.json();if(!response.ok)throw Error(result.error||'Run failed');data.demo=result;notify('M0 passed: 20 messages verified.');}catch(error){lastRunError=error.message;notify('Execution failed: '+error.message);}finally{running=false;render();}}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const d=button.dataset;if(d.flight)flightAction(d.flight);if(d.doc)openDoc(d.doc);if(d.milestone){selectedMilestone=d.milestone;location.hash='milestones';render();}if(d.selectMilestone){selectedMilestone=d.selectMilestone;render();}if(d.systemTab){systemTab=d.systemTab;render();}if(d.packet!==undefined){packetIndex=Number(d.packet);render();}if(d.requirement)openRequirement(d.requirement);if(d.task){const t=data.tasks.find(t=>t.id===d.task);openDialog(t.name,`<div class="dialog-metadata">${badge(t.milestone+(['M2','M3','M4'].includes(t.milestone)?' / implemented':' / planned'),'gray')}${badge(t.priority+' priority','gray')}</div><p>${escapeHTML(t.detail)}</p><div class="detail-section"><h3>OWNED STATE</h3><p>${escapeHTML(t.owns)}</p></div><div class="detail-section"><h3>EXECUTION CADENCE</h3><p>${escapeHTML(t.cadence)}</p></div>`,'TASK CONTRACT');}if(d.report!==undefined){const r=data.reports[Number(d.report)];openDialog(r.label,`<p>Recorded ${date(r.recordedAt)}. A saved result, not a currently running CI job.</p><div class="detail-section">${r.tests.map(t=>`<div class="build-row"><div><strong>${escapeHTML(t.name)}</strong><small>${t.seconds.toFixed(3)} s</small></div>${badge(t.state,t.state==='passed'?'':'amber')}</div>`).join('')}</div>`,'VERIFICATION RECORD');}if(button.id==='inspect-packet')inspectPacket();if(button.id==='corrupt-packet'){const field=$('#packet-hex');const clean=field.value.replace(/\s/g,'');if(clean.length>=4&&!/[^0-9a-f]/i.test(clean)){field.value=clean.slice(0,-2)+(parseInt(clean.slice(-2),16)^1).toString(16).padStart(2,'0');inspectPacket();}}if(button.id==='close-dialog')$('#detail-dialog').close();if(button.id==='refresh')load(true);if(button.id==='run-demo')execute();if(button.id==='export-run'&&data.demo)download('kestrel-m0-run.json',JSON.stringify(data.demo,null,2),'application/json');if(button.id==='export-requirements'){const rows=[['ID','Requirement','Method','Due','Status','Evidence'],...data.requirements.map(r=>[r.id,r.text,r.method,r.due,r.state,r.evidence.join('; ')])];download('kestrel-requirements.csv',rows.map(row=>row.map(cell=>'"'+String(cell).replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv');}});
document.addEventListener('input',event=>{if(event.target.id==='requirement-search'){requirementQuery=event.target.value;requirementRows();}});
document.addEventListener('change',event=>{if(event.target.id==='packet-vector'){capturedPacket=null;packetVector=event.target.value;render();}if(event.target.id==='requirement-milestone'){requirementMilestone=event.target.value;requirementRows();}if(event.target.id==='requirement-state'){requirementState=event.target.value;requirementRows();}});
$('#detail-dialog').addEventListener('click',event=>{if(event.target===$('#detail-dialog'))$('#detail-dialog').close();});
document.addEventListener('toggle',event=>{if(event.target.id==='diagnostics')diagnosticsOpen=event.target.open;},true);
window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});});
setInterval(()=>{if(page==='runtime')pollFlight();},1000);
load();
